/**
 * TopBar Component
 *
 * Main navigation top bar with universe selector following the Minimal Top Bar design (48px height).
 * Provides navigation between Stories and Universe sections.
 */

import { BookOpen, CaretDown, Gear, Globe, Moon, Sun } from '@phosphor-icons/react';
import { useEffect } from 'react';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import { useTheme } from '@/shared/hooks/useTheme';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import './TopBar.css';

export type NavigationTab = 'stories' | 'universe';

interface TopBarProps {
  activeTab?: NavigationTab;
  onTabChange?: (tab: NavigationTab) => void;
}

export function TopBar({ activeTab = 'stories', onTabChange }: TopBarProps) {
  const navigate = useNavigationStore((state) => state.navigate);
  const { currentUniverse, universes, loadUniverses, setCurrentUniverse } = useUniverseStore();
  const { isDark, toggleTheme } = useTheme();

  useEffect(() => {
    loadUniverses();
  }, [loadUniverses]);

  const handleUniverseChange = (event: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedUniverse = universes.find((u) => u.id === event.target.value);
    if (selectedUniverse) {
      setCurrentUniverse(selectedUniverse);
    }
  };

  const handleTabClick = (tab: NavigationTab) => {
    if (onTabChange) {
      onTabChange(tab);
    }
  };

  return (
    <div className="topbar">
      <div className="topbar__left">
        <h1 className="topbar__logo">Bright</h1>

        <div className="topbar__universe-selector">
          <select
            value={currentUniverse?.id || ''}
            onChange={handleUniverseChange}
            className="topbar__select"
            disabled={universes.length === 0}
          >
            {universes.length === 0 ? (
              <option value="">No Universes</option>
            ) : (
              <>
                {!currentUniverse && <option value="">Select Universe</option>}
                {universes.map((universe) => (
                  <option key={universe.id} value={universe.id}>
                    {universe.name}
                  </option>
                ))}
              </>
            )}
          </select>
          <CaretDown className="topbar__select-icon" size={16} />
        </div>
      </div>

      <nav className="topbar__nav">
        <button
          className={`topbar__nav-button ${activeTab === 'stories' ? 'topbar__nav-button--active' : ''}`}
          onClick={() => handleTabClick('stories')}
        >
          <BookOpen size={16} />
          <span>Stories</span>
        </button>

        <button
          className={`topbar__nav-button ${activeTab === 'universe' ? 'topbar__nav-button--active' : ''}`}
          onClick={() => handleTabClick('universe')}
        >
          <Globe size={16} />
          <span>Universe</span>
        </button>

        <div className="topbar__divider" />

        <button
          className="topbar__theme-toggle"
          onClick={toggleTheme}
          title={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
          aria-label={isDark ? 'Switch to light mode' : 'Switch to dark mode'}
        >
          {isDark ? <Sun size={16} /> : <Moon size={16} />}
        </button>

        <button
          className="topbar__settings-button"
          onClick={() => navigate({ screen: 'settings' })}
          title="Settings"
          aria-label="Settings"
        >
          <Gear size={16} />
        </button>
      </nav>
    </div>
  );
}

/**
 * Toast Notification Component
 *
 * Simple toast notification for showing success, error, and info messages.
 */

import { CheckCircle, Info, WarningCircle, X } from '@phosphor-icons/react';
import { useCallback, useEffect, useState } from 'react';
import '@/design-system/tokens/colors/modern-indigo.css';

export type ToastType = 'success' | 'error' | 'info';

export interface ToastMessage {
  id: string;
  type: ToastType;
  message: string;
  duration?: number;
}

interface ToastProps {
  toast: ToastMessage;
  onDismiss: (id: string) => void;
}

function Toast({ toast, onDismiss }: ToastProps) {
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    if (toast.duration !== 0) {
      const timer = setTimeout(() => {
        setIsExiting(true);
        setTimeout(() => onDismiss(toast.id), 200);
      }, toast.duration || 4000);

      return () => clearTimeout(timer);
    }
  }, [toast, onDismiss]);

  const handleDismiss = () => {
    setIsExiting(true);
    setTimeout(() => onDismiss(toast.id), 200);
  };

  const icons = {
    success: <CheckCircle size={18} weight="duotone" />,
    error: <WarningCircle size={18} weight="duotone" />,
    info: <Info size={18} weight="duotone" />,
  };

  const colors = {
    success: 'var(--color-semantic-success)',
    error: 'var(--color-semantic-error)',
    info: 'var(--color-primary)',
  };

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        padding: '12px 16px',
        backgroundColor: 'var(--color-background-primary)',
        border: `1px solid ${colors[toast.type]}`,
        borderRadius: '8px',
        boxShadow: 'var(--shadow-lg)',
        minWidth: '280px',
        maxWidth: '400px',
        opacity: isExiting ? 0 : 1,
        transform: isExiting ? 'translateX(100%)' : 'translateX(0)',
        transition: 'opacity 0.2s, transform 0.2s',
      }}
    >
      <span style={{ color: colors[toast.type], flexShrink: 0 }}>{icons[toast.type]}</span>
      <span
        style={{
          flex: 1,
          color: 'var(--color-text-primary)',
          fontSize: '14px',
        }}
      >
        {toast.message}
      </span>
      <button
        onClick={handleDismiss}
        style={{
          background: 'none',
          border: 'none',
          padding: '4px',
          cursor: 'pointer',
          color: 'var(--color-text-tertiary)',
          flexShrink: 0,
        }}
        aria-label="Dismiss"
      >
        <X size={16} weight="duotone" />
      </button>
    </div>
  );
}

// Toast container for rendering multiple toasts
interface ToastContainerProps {
  toasts: ToastMessage[];
  onDismiss: (id: string) => void;
}

export function ToastContainer({ toasts, onDismiss }: ToastContainerProps) {
  if (toasts.length === 0) return null;

  return (
    <div
      style={{
        position: 'fixed',
        bottom: '24px',
        right: '24px',
        display: 'flex',
        flexDirection: 'column',
        gap: '8px',
        zIndex: 9999,
      }}
    >
      {toasts.map((toast) => (
        <Toast key={toast.id} toast={toast} onDismiss={onDismiss} />
      ))}
    </div>
  );
}

// Hook for managing toasts
export function useToast() {
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  const addToast = useCallback((type: ToastType, message: string, duration?: number) => {
    const id = `toast-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    setToasts((prev) => [...prev, { id, type, message, duration }]);
    return id;
  }, []);

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const success = useCallback(
    (message: string, duration?: number) => addToast('success', message, duration),
    [addToast],
  );

  const error = useCallback(
    (message: string, duration?: number) => addToast('error', message, duration),
    [addToast],
  );

  const info = useCallback(
    (message: string, duration?: number) => addToast('info', message, duration),
    [addToast],
  );

  return {
    toasts,
    addToast,
    dismissToast,
    success,
    error,
    info,
  };
}

/**
 * ErrorBoundary Component
 *
 * Catches JavaScript errors in child component tree and displays a fallback UI.
 * Prevents the entire app from crashing due to errors in individual views.
 */

import { ArrowClockwise, WarningCircle } from '@phosphor-icons/react';
import { Component, type ErrorInfo, type ReactNode } from 'react';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';

interface Props {
  children: ReactNode;
  /** Fallback UI to render when an error occurs */
  fallback?: ReactNode;
  /** Called when an error is caught */
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  /** Name of the component/view for better error messages */
  name?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
    this.props.onError?.(error, errorInfo);
  }

  handleRetry = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback;
      }

      const { name } = this.props;
      const { error } = this.state;

      return (
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '48px',
            gap: '16px',
            minHeight: '200px',
            color: 'var(--color-text-secondary)',
          }}
        >
          <WarningCircle
            size={48}
            weight="duotone"
            style={{ color: 'var(--color-semantic-error)' }}
          />
          <h2 style={{ margin: 0, color: 'var(--color-text-primary)' }}>Something went wrong</h2>
          {name && (
            <p style={{ margin: 0 }}>
              An error occurred in <strong>{name}</strong>
            </p>
          )}
          {error && (
            <code
              style={{
                padding: '8px 16px',
                backgroundColor: 'var(--color-background-secondary)',
                borderRadius: '4px',
                fontSize: '12px',
                maxWidth: '400px',
                overflow: 'auto',
              }}
            >
              {error.message}
            </code>
          )}
          <button
            className="btn btn-primary btn-base"
            onClick={this.handleRetry}
            style={{ marginTop: '8px' }}
          >
            <ArrowClockwise size={16} weight="duotone" />
            Try Again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * UniverseList View
 *
 * Displays all elements in the current universe with filtering, sorting, and search.
 */

import { CircleNotch, GlobeHemisphereWest, MagnifyingGlass, Plus } from '@phosphor-icons/react';
import { useEffect, useState } from 'react';
import { CreateElementModal } from '@/features/elements/components/CreateElementModal';
import { EditElementModal } from '@/features/elements/components/EditElementModal';
import { ElementCard } from '@/features/elements/components/ElementCard';
import { useElementsStore } from '@/features/elements/stores/useElementsStore';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import { ConfirmDeleteModal } from '@/shared/components/ConfirmDeleteModal';
import { PageLayout } from '@/shared/components/PageLayout';
import { ELEMENT_TYPE_OPTIONS } from '@/shared/config/filter-options';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { Element, ElementType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';

type SortOption = 'name' | 'lastEdited' | 'type';

export function UniverseList() {
  const navigate = useNavigationStore((state) => state.navigate);
  const currentUniverse = useUniverseStore((state) => state.currentUniverse);

  const {
    isLoading,
    error,
    loadElements,
    deleteElement,
    updateElement,
    filters,
    setFilter,
    getFilteredElements,
  } = useElementsStore();

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [editingElement, setEditingElement] = useState<Element | null>(null);
  const [deletingElement, setDeletingElement] = useState<Element | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [sortBy, setSortBy] = useState<SortOption>('name');

  // Load elements on mount
  useEffect(() => {
    if (currentUniverse) {
      loadElements(currentUniverse.id);
    }
  }, [currentUniverse, loadElements]);

  const handleTabChange = (tab: 'stories' | 'universe') => {
    if (tab === 'stories') {
      navigate({ screen: 'stories-list' });
    }
  };

  const handleElementClick = (element: Element) => {
    navigate({ screen: 'element-detail', elementId: element.id });
  };

  const handleEditElement = (element: Element) => {
    setEditingElement(element);
  };

  const handleDeleteElement = (element: Element) => {
    setDeletingElement(element);
  };

  const handleConfirmDelete = async () => {
    if (!deletingElement) return;

    setIsDeleting(true);
    try {
      await deleteElement(deletingElement.id);
      setDeletingElement(null);
    } catch (error) {
      console.error('Failed to delete element:', error);
    } finally {
      setIsDeleting(false);
    }
  };

  const handleCancelDelete = () => {
    setDeletingElement(null);
  };

  const handleToggleFavorite = async (element: Element) => {
    try {
      await updateElement(element.id, {
        name: null,
        description: null,
        elementType: null,
        customTypeName: null,
        details: null,
        attributes: null,
        imageUrl: null,
        tags: null,
        relationships: null,
        color: null,
        icon: null,
        favorite: !element.favorite,
        relatedStoryIds: null,
        order: null,
      });
    } catch (error) {
      console.error('Failed to toggle favorite:', error);
    }
  };

  // Get filtered and sorted elements
  const filteredElements = getFilteredElements();

  // Apply sorting
  const sortedElements = [...filteredElements].sort((a, b) => {
    switch (sortBy) {
      case 'name':
        return a.name.localeCompare(b.name);
      case 'lastEdited':
        return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
      case 'type':
        return a.elementType.localeCompare(b.elementType);
      default:
        return 0;
    }
  });

  return (
    <PageLayout activeTab="universe" onTabChange={handleTabChange}>
      <div
        className="option-1 typo-1 icons-1 button-2 input-5"
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          padding: 'var(--spacing-6)',
        }}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: 'var(--spacing-6)',
          }}
        >
          <h1
            style={{
              fontFamily: 'var(--typography-heading-font)',
              fontSize: 'var(--typography-h2-size)',
              fontWeight: 'var(--typography-h2-weight)',
              color: 'var(--color-text-primary)',
              margin: 0,
            }}
          >
            Universe Elements
          </h1>
          <button className="btn btn-primary btn-base" onClick={() => setShowCreateModal(true)}>
            <Plus className="icon icon-base" />
            New Element
          </button>
        </div>

        {/* Toolbar */}
        <div
          style={{
            display: 'flex',
            gap: 'var(--spacing-3)',
            marginBottom: 'var(--spacing-6)',
            flexWrap: 'wrap',
          }}
        >
          {/* Search */}
          <div className="input-group input-5" style={{ flex: '1', minWidth: '250px' }}>
            <div className="input-wrapper">
              <div className="input-icon-prefix">
                <MagnifyingGlass className="icon icon-base" weight="duotone" />
              </div>
              <input
                type="text"
                className="input-field input-base has-prefix"
                placeholder="Search elements..."
                value={filters.searchQuery}
                onChange={(e) => setFilter('searchQuery', e.target.value)}
              />
            </div>
          </div>

          {/* Filter by Type */}
          <div className="input-group input-5" style={{ minWidth: '150px' }}>
            <select
              className="input-field input-base"
              value={filters.type || ''}
              onChange={(e) =>
                setFilter('type', e.target.value ? (e.target.value as ElementType) : null)
              }
              style={{
                backgroundColor: 'var(--color-surface)',
                border: '1px solid var(--color-border)',
                borderRadius: '4px',
                padding: 'var(--spacing-2) var(--spacing-3)',
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-primary)',
              }}
            >
              <option value="">All Types</option>
              {ELEMENT_TYPE_OPTIONS.map(({ value, label }) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </div>

          {/* Sort */}
          <div className="input-group input-5" style={{ minWidth: '150px' }}>
            <select
              className="input-field input-base"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as SortOption)}
              style={{
                backgroundColor: 'var(--color-surface)',
                border: '1px solid var(--color-border)',
                borderRadius: '4px',
                padding: 'var(--spacing-2) var(--spacing-3)',
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-primary)',
              }}
            >
              <option value="name">Name</option>
              <option value="lastEdited">Recently Updated</option>
              <option value="type">Type</option>
            </select>
          </div>
        </div>

        {/* Error State */}
        {error && (
          <div
            style={{
              padding: 'var(--spacing-4)',
              backgroundColor: 'var(--color-error-subtle)',
              color: 'var(--color-error)',
              borderRadius: '4px',
              marginBottom: 'var(--spacing-6)',
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-sm)',
            }}
          >
            {error}
          </div>
        )}

        {/* Loading State */}
        {isLoading && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
              gap: 'var(--spacing-3)',
            }}
          >
            <CircleNotch
              className="icon icon-2xl"
              style={{
                color: 'var(--color-primary)',
                animation: 'spin 1s linear infinite',
              }}
            />
            <p
              style={{
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-secondary)',
              }}
            >
              Loading elements...
            </p>
          </div>
        )}

        {/* Empty State */}
        {!isLoading && sortedElements.length === 0 && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
              gap: 'var(--spacing-4)',
              textAlign: 'center',
            }}
          >
            <GlobeHemisphereWest
              size={64}
              weight="duotone"
              style={{
                color: 'var(--color-text-secondary)',
                opacity: 0.4,
              }}
            />
            <h2
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--typography-h3-size)',
                fontWeight: 'var(--typography-h3-weight)',
                color: 'var(--color-text-primary)',
                margin: 0,
              }}
            >
              No elements yet
            </h2>
            <p
              style={{
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-secondary)',
                maxWidth: '400px',
              }}
            >
              {filters.searchQuery || filters.type
                ? 'No elements match your filters. Try adjusting your search or filters.'
                : 'Build your universe by creating your first element!'}
            </p>
            {!filters.searchQuery && !filters.type && (
              <button className="btn btn-primary btn-lg" onClick={() => setShowCreateModal(true)}>
                <Plus className="icon icon-base" />
                Create Your First Element
              </button>
            )}
          </div>
        )}

        {/* Elements Grid */}
        {!isLoading && sortedElements.length > 0 && (
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
              gap: 'var(--spacing-6)',
              alignItems: 'start',
            }}
          >
            {sortedElements.map((element) => (
              <ElementCard
                key={element.id}
                element={element}
                onClick={handleElementClick}
                onEdit={handleEditElement}
                onDelete={handleDeleteElement}
                onToggleFavorite={handleToggleFavorite}
              />
            ))}
          </div>
        )}
      </div>

      {/* Create Element Modal */}
      {showCreateModal && <CreateElementModal onClose={() => setShowCreateModal(false)} />}

      {/* Edit Element Modal */}
      {editingElement && (
        <EditElementModal
          element={editingElement}
          onClose={() => setEditingElement(null)}
          onSuccess={() => {
            // Reload elements to get the updated data
            if (currentUniverse) {
              loadElements(currentUniverse.id);
            }
            setEditingElement(null);
          }}
        />
      )}

      {/* Delete Confirmation Modal */}
      {deletingElement && (
        <ConfirmDeleteModal
          title="Delete Element"
          message="Are you sure you want to delete this element? This action cannot be undone."
          itemName={deletingElement.name}
          onConfirm={handleConfirmDelete}
          onCancel={handleCancelDelete}
          isDeleting={isDeleting}
        />
      )}

      {/* Spinner animation */}
      <style>
        {`
          @keyframes spin {
            from {
              transform: rotate(0deg);
            }
            to {
              transform: rotate(360deg);
            }
          }
        `}
      </style>
    </PageLayout>
  );
}

/**
 * StoryHistory View
 *
 * Displays database snapshots for a story's active version.
 * Part of the Database-Only Versioning (DBV) system.
 *
 * Features:
 * - Lists all snapshots for the active version (newest first)
 * - Shows creation timestamp for each snapshot
 * - Allows restoring to any previous snapshot
 * - No manual delete (retention policy handles cleanup)
 */

import { ArrowCounterClockwise, ArrowLeft, Clock, SpinnerGap } from '@phosphor-icons/react';
import { useCallback, useEffect, useState } from 'react';
import { useSettingsStore } from '@/features/settings/stores/useSettingsStore';
import { listStorySnapshots, switchStorySnapshot } from '@/features/stories/api/snapshots';
import { useStoriesStore } from '@/features/stories/stores/useStoriesStore';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import { useToastStore } from '@/shared/stores/useToastStore';
import { countLexicalWords } from '@/shared/utils/lexicalWordCount';
import type { StoryDetail, StorySnapshot } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/spacing.css';
import './StoryHistory.css';

/**
 * Format a timestamp to an absolute date/time format.
 * Example: "Jan 20, 2026 2:30 PM"
 */
function formatTimestamp(isoString: string): string {
  const date = new Date(isoString);
  return date.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  });
}

export function StoryHistory() {
  const currentRoute = useNavigationStore((state) => state.currentRoute);
  const goBack = useNavigationStore((state) => state.goBack);
  const maxSnapshotsPerVersion = useSettingsStore((state) => state.maxSnapshotsPerVersion);
  const getStory = useStoriesStore((state) => state.getStory);
  const showSuccess = useToastStore((state) => state.success);
  const showError = useToastStore((state) => state.error);

  const [story, setStory] = useState<StoryDetail | null>(null);
  const [snapshots, setSnapshots] = useState<StorySnapshot[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [restoringId, setRestoringId] = useState<string | null>(null);

  // Extract story ID from route
  const storyId = currentRoute.screen === 'story-history' ? currentRoute.storyId : null;

  // Load story and snapshots
  useEffect(() => {
    if (!storyId) return;

    const loadData = async () => {
      setIsLoading(true);
      setError(null);

      try {
        // Load story first to get active_version_id
        const loadedStory = await getStory(storyId);
        setStory(loadedStory);

        // If story has an active version, load its snapshots
        if (loadedStory.activeVersionId) {
          const loadedSnapshots = await listStorySnapshots(loadedStory.activeVersionId);
          setSnapshots(loadedSnapshots);
        } else {
          setSnapshots([]);
        }
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Failed to load snapshots';
        setError(message);
        showError(message);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, [storyId, getStory, showError]);

  // Handle restoring a snapshot
  const handleRestore = useCallback(
    async (snapshotId: string) => {
      if (!storyId || restoringId) return;

      const snapshotToRestore = snapshots.find((snapshot) => snapshot.id === snapshotId);
      if (!snapshotToRestore) {
        showError('Snapshot not found');
        return;
      }

      setRestoringId(snapshotId);

      try {
        await switchStorySnapshot({
          storyId,
          snapshotId,
          wordCount: countLexicalWords(snapshotToRestore.content),
          maxSnapshots: maxSnapshotsPerVersion,
        });

        // Re-fetch story as StoryDetail after snapshot switch
        const updatedStory = await getStory(storyId);
        setStory(updatedStory);

        if (updatedStory.activeVersionId) {
          const refreshedSnapshots = await listStorySnapshots(updatedStory.activeVersionId);
          setSnapshots(refreshedSnapshots);
        }

        showSuccess('Snapshot restored successfully');
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Failed to restore snapshot';
        showError(message);
      } finally {
        setRestoringId(null);
      }
    },
    [storyId, restoringId, snapshots, maxSnapshotsPerVersion, showSuccess, showError],
  );

  // Loading state
  if (isLoading) {
    return (
      <div className="story-history-loading">
        <SpinnerGap size={48} weight="duotone" className="spinner" />
        <p>Loading snapshots...</p>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="story-history-error">
        <p>{error}</p>
        <button className="btn btn-outline btn-base" onClick={goBack}>
          <ArrowLeft size={18} />
          Go Back
        </button>
      </div>
    );
  }

  return (
    <div className="story-history">
      <div className="story-history-header">
        <button className="back-button" onClick={goBack} aria-label="Go back" title="Go back">
          <ArrowLeft size={20} />
        </button>
        <div className="header-content">
          <h1 className="page-title">Snapshots</h1>
          {story && <p className="story-name">{story.title}</p>}
        </div>
      </div>

      <div className="timeline-container">
        {snapshots.length === 0 ? (
          <div className="empty-state">
            <Clock size={48} />
            <h2>No Snapshots Yet</h2>
            <p className="empty-state-hint">
              Snapshots are created automatically as you write.
              <br />
              Keep writing and your progress will be saved here.
            </p>
          </div>
        ) : (
          <div className="timeline">
            {snapshots.map((snapshot, index) => {
              const isCurrentSnapshot = story?.activeSnapshotId === snapshot.id;
              const isRestoring = restoringId === snapshot.id;
              const isLastItem = index === snapshots.length - 1;

              return (
                <div key={snapshot.id} className="timeline-item">
                  <div className="timeline-marker">
                    <div className={`timeline-dot ${isCurrentSnapshot ? 'active' : ''}`} />
                    {!isLastItem && <div className="timeline-line" />}
                  </div>
                  <div className={`snapshot-card ${isCurrentSnapshot ? 'current' : ''}`}>
                    <div className="snapshot-header">
                      <span className="snapshot-time" title={snapshot.createdAt}>
                        {formatTimestamp(snapshot.createdAt)}
                      </span>
                      {isCurrentSnapshot ? (
                        <span className="current-badge">Current</span>
                      ) : (
                        <button
                          className="btn btn-outline btn-sm restore-button"
                          onClick={() => handleRestore(snapshot.id)}
                          disabled={isRestoring || restoringId !== null}
                          aria-label="Restore this snapshot"
                          title="Restore this snapshot"
                        >
                          {isRestoring ? (
                            <SpinnerGap size={14} className="spinner" />
                          ) : (
                            <ArrowCounterClockwise size={14} />
                          )}
                          Restore
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

