/**
 * StoriesList View
 *
 * Displays all stories in the current universe with filtering, sorting, and search.
 */

import { Books, CircleNotch, FolderPlus, MagnifyingGlass, Plus } from '@phosphor-icons/react';
import { useEffect, useState } from 'react';
import { ContainerCard } from '@/features/containers/components/ContainerCard';
import { CreateContainerModal } from '@/features/containers/components/CreateContainerModal';
import { useContainersStore } from '@/features/containers/stores/useContainersStore';
import { CreateStoryModal } from '@/features/stories/components/CreateStoryModal';
import { DeleteStoryModal } from '@/features/stories/components/DeleteStoryModal';
import { StoryCard } from '@/features/stories/components/StoryCard';
import { useStoriesStore } from '@/features/stories/stores/useStoriesStore';
import { useUniverseStore } from '@/features/universe/stores/useUniverseStore';
import { PageLayout } from '@/shared/components/PageLayout';
import { CONTAINER_TYPE_OPTIONS, STORY_TYPE_OPTIONS } from '@/shared/config/filter-options';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import type { Container, StorySummary, StoryType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';

export function StoriesList() {
  const navigate = useNavigationStore((state) => state.navigate);
  const currentUniverse = useUniverseStore((state) => state.currentUniverse);

  const {
    isLoading,
    error,
    loadStories,
    deleteStory,
    updateStory,
    filters,
    setFilter,
    getFilteredAndSortedStories,
    setSorting,
    sortBy,
    sortOrder,
  } = useStoriesStore();

  const {
    isLoading: containersLoading,
    error: containersError,
    loadContainers,
    deleteContainer,
    filters: containerFilters,
    setFilter: setContainerFilter,
    getFilteredContainers,
  } = useContainersStore();

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showCreateContainerModal, setShowCreateContainerModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [storyToDelete, setStoryToDelete] = useState<StorySummary | null>(null);
  const [deleteChildCount, setDeleteChildCount] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);
  const [containerToDelete, setContainerToDelete] = useState<Container | null>(null);
  const [showDeleteContainerModal, setShowDeleteContainerModal] = useState(false);
  const [isDeletingContainer, setIsDeletingContainer] = useState(false);

  // Load stories and containers on mount
  useEffect(() => {
    if (currentUniverse) {
      loadStories(currentUniverse.id);
      loadContainers(currentUniverse.id);
    }
  }, [currentUniverse, loadStories, loadContainers]);

  const handleTabChange = (tab: 'stories' | 'universe') => {
    if (tab === 'universe') {
      navigate({ screen: 'universe-list' });
    }
  };

  const handleStoryClick = (story: StorySummary) => {
    // All stories are content now - always navigate to editor
    navigate({ screen: 'story-editor', storyId: story.id });
  };

  const handleDeleteStory = async (story: StorySummary) => {
    // Stories no longer have children (handled by containers)
    setStoryToDelete(story);
    setDeleteChildCount(0);
    setShowDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!storyToDelete) return;

    setIsDeleting(true);
    try {
      await deleteStory(storyToDelete.id);
      // Close modal and reset state
      setShowDeleteModal(false);
      setStoryToDelete(null);
      setDeleteChildCount(0);
    } catch (error) {
      console.error('Failed to delete story:', error);
      // Keep modal open to show error (error is already in store)
    } finally {
      setIsDeleting(false);
    }
  };

  const handleCancelDelete = () => {
    setShowDeleteModal(false);
    setStoryToDelete(null);
    setDeleteChildCount(0);
    setIsDeleting(false);
  };

  const handleToggleFavorite = async (story: StorySummary) => {
    try {
      // Note: Only pass favorite field - content is managed via DBV (versions/snapshots)
      await updateStory(story.id, {
        favorite: !story.favorite,
      });
    } catch (error) {
      console.error('Failed to toggle favorite:', error);
    }
  };

  const handleContainerClick = (container: Container) => {
    navigate({ screen: 'container-view', containerId: container.id });
  };

  const handleDeleteContainer = async (container: Container) => {
    setContainerToDelete(container);
    setShowDeleteContainerModal(true);
  };

  const handleConfirmDeleteContainer = async () => {
    if (!containerToDelete) return;

    setIsDeletingContainer(true);
    try {
      await deleteContainer(containerToDelete.id);
      setShowDeleteContainerModal(false);
      setContainerToDelete(null);
    } catch (error) {
      console.error('Failed to delete container:', error);
    } finally {
      setIsDeletingContainer(false);
    }
  };

  const handleCancelDeleteContainer = () => {
    setShowDeleteContainerModal(false);
    setContainerToDelete(null);
    setIsDeletingContainer(false);
  };

  // Get filtered and sorted stories (grouped view - top level only)
  // Filter to show only stories not in containers (root stories)
  const filteredStories = getFilteredAndSortedStories().filter((story) => !story.containerId);

  // Get root-level containers (no parentContainerId) with filtering applied
  const rootContainers = getFilteredContainers().filter((c) => !c.parentContainerId);

  // Stories no longer have children (that's handled by containers now)

  return (
    <PageLayout activeTab="stories" onTabChange={handleTabChange}>
      <div
        className="option-1 typo-1 icons-1 button-2 input-5"
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: '100%',
          padding: 'var(--spacing-6)',
        }}
      >
        {/* Header */}
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            marginBottom: 'var(--spacing-6)',
          }}
        >
          <h1
            style={{
              fontFamily: 'var(--typography-heading-font)',
              fontSize: 'var(--typography-h2-size)',
              fontWeight: 'var(--typography-h2-weight)',
              color: 'var(--color-text-primary)',
              margin: 0,
            }}
          >
            Stories
          </h1>
          <div style={{ display: 'flex', gap: 'var(--spacing-3)' }}>
            <button
              className="btn btn-outline btn-base"
              onClick={() => setShowCreateContainerModal(true)}
              title="Create a container (Novel, Series, Collection)"
            >
              <FolderPlus className="icon icon-base" />
              New Container
            </button>
            <button
              className="btn btn-primary btn-base"
              onClick={() => setShowCreateModal(true)}
              title="Create a standalone story"
            >
              <Plus className="icon icon-base" />
              New Story
            </button>
          </div>
        </div>

        {/* Toolbar */}
        <div
          style={{
            display: 'flex',
            gap: 'var(--spacing-3)',
            marginBottom: 'var(--spacing-6)',
            flexWrap: 'wrap',
          }}
        >
          {/* Search (unified for both containers and stories) */}
          <div className="input-group input-5" style={{ flex: '1', minWidth: '250px' }}>
            <div className="input-wrapper">
              <div className="input-icon-prefix">
                <MagnifyingGlass className="icon icon-base" weight="duotone" />
              </div>
              <input
                type="text"
                className="input-field input-base has-prefix"
                placeholder="Search stories and containers..."
                value={filters.searchQuery}
                onChange={(e) => {
                  const value = e.target.value;
                  setFilter('searchQuery', value);
                  setContainerFilter('searchQuery', value);
                }}
              />
            </div>
          </div>

          {/* Filter by Container Type */}
          <div className="input-group input-5" style={{ minWidth: '150px' }}>
            <select
              className="input-field input-base"
              value={containerFilters.containerType || ''}
              onChange={(e) => setContainerFilter('containerType', e.target.value || null)}
            >
              <option value="">All Containers</option>
              {CONTAINER_TYPE_OPTIONS.map(({ value, label }) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </div>

          {/* Filter by Story Type */}
          <div className="input-group input-5" style={{ minWidth: '150px' }}>
            <select
              className="input-field input-base"
              value={filters.type || ''}
              onChange={(e) =>
                setFilter('type', e.target.value ? (e.target.value as StoryType) : null)
              }
            >
              <option value="">All Story Types</option>
              {STORY_TYPE_OPTIONS.map(({ value, label }) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </div>

          {/* Sort */}
          <div className="input-group input-5" style={{ minWidth: '150px' }}>
            <select
              className="input-field input-base"
              value={sortBy}
              onChange={(e) =>
                setSorting(e.target.value as 'lastEdited' | 'title' | 'wordCount', sortOrder)
              }
            >
              <option value="lastEdited">Last Edited</option>
              <option value="title">Title</option>
              <option value="wordCount">Word Count</option>
            </select>
          </div>

          {/* Sort Order */}
          <button
            className="btn btn-outline btn-base"
            onClick={() => setSorting(sortBy, sortOrder === 'asc' ? 'desc' : 'asc')}
            title={sortOrder === 'asc' ? 'Ascending' : 'Descending'}
          >
            {sortOrder === 'asc' ? '↑' : '↓'}
          </button>
        </div>

        {/* Error State */}
        {(error || containersError) && (
          <div
            style={{
              padding: 'var(--spacing-4)',
              backgroundColor: 'var(--color-error-subtle)',
              color: 'var(--color-error)',
              borderRadius: '4px',
              marginBottom: 'var(--spacing-6)',
              fontFamily: 'var(--typography-body-font)',
              fontSize: 'var(--font-size-sm)',
            }}
          >
            {error || containersError}
          </div>
        )}

        {/* Loading State */}
        {(isLoading || containersLoading) && (
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
              gap: 'var(--spacing-3)',
            }}
          >
            <CircleNotch
              className="icon icon-2xl"
              style={{
                color: 'var(--color-primary)',
                animation: 'spin 1s linear infinite',
              }}
            />
            <p
              style={{
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-secondary)',
              }}
            >
              Loading...
            </p>
          </div>
        )}

        {/* Content Grid - Containers and Stories together */}
        {!isLoading &&
          !containersLoading &&
          (rootContainers.length > 0 || filteredStories.length > 0) && (
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
                gap: 'var(--spacing-6)',
                alignItems: 'start',
              }}
            >
              {rootContainers.map((container) => (
                <ContainerCard
                  key={container.id}
                  container={container}
                  onClick={handleContainerClick}
                  onDelete={handleDeleteContainer}
                />
              ))}
              {filteredStories.map((story) => (
                <StoryCard
                  key={story.id}
                  story={story}
                  onClick={handleStoryClick}
                  onDelete={handleDeleteStory}
                  onToggleFavorite={handleToggleFavorite}
                />
              ))}
            </div>
          )}

        {/* Empty State */}
        {!isLoading &&
          !containersLoading &&
          filteredStories.length === 0 &&
          rootContainers.length === 0 && (
            <div
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                flex: 1,
                gap: 'var(--spacing-4)',
                textAlign: 'center',
              }}
            >
              <Books
                size={64}
                weight="duotone"
                style={{
                  color: 'var(--color-text-secondary)',
                  opacity: 0.4,
                }}
              />
              <h2
                style={{
                  fontFamily: 'var(--typography-heading-font)',
                  fontSize: 'var(--typography-h3-size)',
                  fontWeight: 'var(--typography-h3-weight)',
                  color: 'var(--color-text-primary)',
                  margin: 0,
                }}
              >
                No stories yet
              </h2>
              <p
                style={{
                  fontFamily: 'var(--typography-body-font)',
                  fontSize: 'var(--font-size-base)',
                  color: 'var(--color-text-secondary)',
                  maxWidth: '400px',
                }}
              >
                {filters.searchQuery || filters.type || filters.status
                  ? 'No stories match your filters. Try adjusting your search or filters.'
                  : 'Get started by creating your first story!'}
              </p>
              {!filters.searchQuery && !filters.type && !filters.status && (
                <button className="btn btn-primary btn-lg" onClick={() => setShowCreateModal(true)}>
                  <Plus className="icon icon-base" />
                  Create Your First Story
                </button>
              )}
            </div>
          )}
      </div>

      {/* Create Container Modal */}
      {showCreateContainerModal && (
        <CreateContainerModal onClose={() => setShowCreateContainerModal(false)} />
      )}

      {/* Create Story Modal */}
      {showCreateModal && <CreateStoryModal onClose={() => setShowCreateModal(false)} />}

      {/* Delete Story Modal */}
      <DeleteStoryModal
        isOpen={showDeleteModal}
        story={storyToDelete}
        childCount={deleteChildCount}
        onConfirm={handleConfirmDelete}
        onCancel={handleCancelDelete}
        isDeleting={isDeleting}
      />

      {/* Delete Container Modal */}
      {showDeleteContainerModal && containerToDelete && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
          }}
          onClick={handleCancelDeleteContainer}
        >
          <div
            className="card card-base option-1 typo-1 button-2"
            onClick={(e) => e.stopPropagation()}
            style={{
              maxWidth: '500px',
              padding: 'var(--spacing-6)',
            }}
          >
            <h2
              style={{
                fontFamily: 'var(--typography-heading-font)',
                fontSize: 'var(--typography-h3-size)',
                fontWeight: 'var(--typography-h3-weight)',
                color: 'var(--color-text-primary)',
                margin: 0,
                marginBottom: 'var(--spacing-4)',
              }}
            >
              Delete Container?
            </h2>
            <p
              style={{
                fontFamily: 'var(--typography-body-font)',
                fontSize: 'var(--font-size-base)',
                color: 'var(--color-text-secondary)',
                margin: 0,
                marginBottom: 'var(--spacing-6)',
              }}
            >
              Are you sure you want to delete "{containerToDelete.title}"? This action cannot be
              undone. All child containers and stories will also be deleted.
            </p>
            <div style={{ display: 'flex', gap: 'var(--spacing-3)', justifyContent: 'flex-end' }}>
              <button
                className="btn btn-outline btn-base"
                onClick={handleCancelDeleteContainer}
                disabled={isDeletingContainer}
              >
                Cancel
              </button>
              <button
                className="btn btn-primary btn-base"
                onClick={handleConfirmDeleteContainer}
                disabled={isDeletingContainer}
                style={{
                  backgroundColor: 'var(--color-error)',
                }}
              >
                {isDeletingContainer ? 'Deleting...' : 'Delete'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Spinner animation */}
      <style>
        {`
          @keyframes spin {
            from {
              transform: rotate(0deg);
            }
            to {
              transform: rotate(360deg);
            }
          }
        `}
      </style>
    </PageLayout>
  );
}

/**
 * Story Settings View
 *
 * Full-page view for editing story metadata after creation.
 * Allows users to update title, description, story type, and target word count.
 */

import { ArrowLeft } from '@phosphor-icons/react';
import { type FormEvent, useEffect, useState } from 'react';
import { useStoriesStore } from '@/features/stories/stores/useStoriesStore';
import { useNavigationStore } from '@/shared/stores/useNavigationStore';
import { useToastStore } from '@/shared/stores/useToastStore';
import type { StoryDetail, StoryType } from '@/types';
import '@/design-system/tokens/colors/modern-indigo.css';
import '@/design-system/tokens/typography/classic-serif.css';
import '@/design-system/tokens/icons/phosphor.css';
import '@/design-system/tokens/atoms/button/minimal-squared.css';
import '@/design-system/tokens/atoms/input/filled-background.css';
import '@/design-system/tokens/spacing.css';
import '@/features/settings/views/SettingsPage.css';

export function StorySettings() {
  const currentRoute = useNavigationStore((state) => state.currentRoute);
  const goBack = useNavigationStore((state) => state.goBack);
  const canGoBack = useNavigationStore((state) => state.canGoBack);
  const navigate = useNavigationStore((state) => state.navigate);
  const getStory = useStoriesStore((state) => state.getStory);
  const updateStory = useStoriesStore((state) => state.updateStory);
  const showSuccess = useToastStore((state) => state.success);
  const showError = useToastStore((state) => state.error);

  const [story, setStory] = useState<StoryDetail | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    storyType: 'novel' as StoryType,
    targetWordCount: '',
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Extract story ID from route
  const storyId = currentRoute.screen === 'story-settings' ? currentRoute.storyId : null;

  // Load story on mount
  useEffect(() => {
    if (!storyId) return;

    const loadStoryData = async () => {
      setIsLoading(true);
      try {
        const loadedStory = await getStory(storyId);
        setStory(loadedStory);
        setFormData({
          title: loadedStory.title,
          description: loadedStory.description,
          storyType: loadedStory.storyType,
          targetWordCount: loadedStory.targetWordCount?.toString() || '',
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : 'Failed to load story';
        showError(message);
      } finally {
        setIsLoading(false);
      }
    };

    loadStoryData();
  }, [storyId, getStory, showError]);

  const handleBack = () => {
    if (canGoBack()) {
      goBack();
    } else {
      // Fallback to stories list if no history
      navigate({ screen: 'stories-list' });
    }
  };

  const handleCancel = () => {
    handleBack();
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    // Validate
    const newErrors: Record<string, string> = {};
    if (!formData.title.trim()) {
      newErrors.title = 'Title is required';
    }
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    if (!storyId) {
      showError('Story ID not found');
      return;
    }

    // Submit
    setIsSubmitting(true);
    setErrors({});

    try {
      await updateStory(storyId, {
        title: formData.title.trim(),
        description: formData.description.trim(),
        storyType: formData.storyType,
        targetWordCount: formData.targetWordCount ? parseInt(formData.targetWordCount, 10) : null,
      });

      showSuccess('Story settings updated');
      handleBack();
    } catch (error) {
      console.error('Failed to update story settings:', error);
      showError(error instanceof Error ? error.message : 'Failed to update story settings');
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="settings-page">
        <div className="settings-page__loading">Loading story settings...</div>
      </div>
    );
  }

  if (!story) {
    return (
      <div className="settings-page">
        <div className="settings-page__error">Story not found</div>
      </div>
    );
  }

  return (
    <div className="settings-page option-1 typo-1 icons-1 button-2 input-5">
      {/* Header */}
      <div className="settings-page__header">
        <button
          className="settings-page__back-button"
          onClick={handleBack}
          aria-label="Go back"
          title="Back"
        >
          <ArrowLeft size={20} weight="duotone" />
        </button>

        <div className="settings-page__header-content">
          <h1 className="settings-page__title">Story Settings</h1>
          <p className="settings-page__subtitle">Edit story metadata</p>
        </div>
      </div>

      {/* Form */}
      <div className="settings-page__content">
        <form onSubmit={handleSubmit}>
          <div className="settings-page__form-fields">
            {/* General Error */}
            {errors.general && <div className="settings-page__error-banner">{errors.general}</div>}

            {/* Story Type */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="story-type">
                Story Type
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <select
                  id="story-type"
                  className="input-field input-base"
                  value={formData.storyType}
                  onChange={(e) =>
                    setFormData({ ...formData, storyType: e.target.value as StoryType })
                  }
                  disabled={isSubmitting}
                >
                  <option value="novel">Novel</option>
                  <option value="series">Series</option>
                  <option value="screenplay">Screenplay</option>
                  <option value="short-story">Short Story</option>
                  <option value="poem">Poem</option>
                  <option value="chapter">Chapter</option>
                  <option value="scene">Scene</option>
                  <option value="episode">Episode</option>
                  <option value="outline">Outline</option>
                  <option value="treatment">Treatment</option>
                  <option value="collection">Collection</option>
                </select>
              </div>
            </div>

            {/* Title */}
            <div className={`input-group input-5 ${errors.title ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="story-title">
                Title
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <input
                  id="story-title"
                  type="text"
                  className="input-field input-base"
                  placeholder="Enter story title"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  disabled={isSubmitting}
                  required
                />
              </div>
              {errors.title && <div className="input-helper">{errors.title}</div>}
            </div>

            {/* Description */}
            <div className={`input-group input-5 ${errors.description ? 'has-error' : ''}`}>
              <label className="input-label" htmlFor="story-description">
                Description
                <span className="required">*</span>
              </label>
              <div className="input-wrapper">
                <textarea
                  id="story-description"
                  className="input-field input-base"
                  placeholder="Brief description of your story"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  rows={3}
                  disabled={isSubmitting}
                  required
                  style={{
                    resize: 'vertical',
                    minHeight: '80px',
                  }}
                />
              </div>
              {errors.description && <div className="input-helper">{errors.description}</div>}
            </div>

            {/* Target Word Count */}
            <div className="input-group input-5">
              <label className="input-label" htmlFor="story-word-count">
                Target Word Count
              </label>
              <div className="input-wrapper">
                <input
                  id="story-word-count"
                  type="number"
                  className="input-field input-base"
                  placeholder="e.g., 80000"
                  value={formData.targetWordCount}
                  onChange={(e) => setFormData({ ...formData, targetWordCount: e.target.value })}
                  disabled={isSubmitting}
                  min="0"
                />
              </div>
              <div className="input-helper">Optional goal for story length</div>
            </div>
          </div>

          {/* Footer */}
          <div className="settings-page__footer">
            <button
              type="button"
              className="btn btn-ghost btn-base"
              onClick={handleCancel}
              disabled={isSubmitting}
            >
              Cancel
            </button>
            <button type="submit" className="btn btn-primary btn-base" disabled={isSubmitting}>
              {isSubmitting ? 'Saving...' : 'Save'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

